// Make text safe to put inside an HTML email
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (n) => n == null || n === '' ? '-' : '$' + Math.round(Number(n)).toLocaleString('en-US');

const deals = $input.all().map(i => i.json);
const rows = deals.map(d => `
  <tr>
    <td><b>${esc(d.discount_pct)}%</b>${d.suspicious ? '<br><span style="color:#b00">too cheap - check for fake/scam</span>' : ''}</td>
    <td>${esc(d.brand)} ${esc(d.reference)}<br><small>${esc(d.title)}</small></td>
    <td>${esc(d.condition)}</td>
    <td>${esc(d.price)} ${esc(d.currency)}<br><small>${money(d.price_usd)}</small></td>
    <td>${money(d.fair_usd)}</td>
    <td>${esc(d.country)}</td>
    <td>${esc(d.source)}<br><small>${esc(d.seller)}</small></td>
    <td>${d.url ? `<a href="${esc(d.url)}">open</a>` : ''}</td>
  </tr>`).join('');

return [{
  json: {
    owner_email: deals[0].owner_email,
    from_email: deals[0].from_email,
    subject: `${deals.length} underpriced watch${deals.length > 1 ? 'es' : ''} found (best: ${deals[0].discount_pct}% below fair price)`,
    html: `<p>New listings below fair price. Always check the seller, photos and papers before buying.</p>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:Arial;font-size:13px">
<tr style="background:#eee"><th>Below fair</th><th>Watch</th><th>Condition</th><th>Price</th><th>Fair price</th><th>Country</th><th>Source</th><th>Link</th></tr>
${rows}
</table>`,
  },
}];

// When the database query finds nothing, n8n still passes one item: {"success": true}.
// Remove it so the next steps only run for real rows.
return $input.all()
  .map((item, index) => ({ json: item.json, pairedItem: { item: index } }))
  .filter(item => !(Object.keys(item.json).length === 1 && item.json.success === true));
